const text = $input.first().json.text || $input.first().json.html || '';
const subject = $input.first().json.subject || '';
const from = $input.first().json.from || '';

// Immatriculation
const immatRegex = /\b([A-Z]{2}[-\s]?\d{3}[-\s]?[A-Z]{2})\b/gi;
const immat = (text.match(immatRegex) || [])[0] || 'Non detectee';

// Client
const clientMatch = text.match(/(?:client|nom)[\s:]+([A-Z][a-z\s]+)/i);
const client = clientMatch ? clientMatch[1].trim() : 'Non detecte';

// Société
const societeMatch = text.match(/(?:societe|entreprise)[\s:]+([A-Z][^\n,]+)/i);
const societe = societeMatch ? societeMatch[1].trim() : 'Non detectee';

// Loueur
const loueurs = ['ALD','Arval','LeasePlan','Alphabet','Athlon'];
const loueur = loueurs.find(l => text.includes(l)) || 'Non indique';

// Dimensions pneus
const dimRegex = /\b\d{3}\/\d{2}[A-Z]\d{2}[^\s,;]*/gi;
const dims = [...new Set((text.match(dimRegex) || []))];

// Codes SAP
const sapRegex = /\b\d{6,8}\b/g;
const saps = [...new Set((text.match(sapRegex) || []))];

return [{
  json: {
    type: 'PNEUS',
    sujet: subject,
    expediteur: from,
    immatriculation: immat,
    client: client,
    societe: societe,
    loueur: loueur,
    dimensions: dims,
    codesSAP: saps,
    nbPneus: dims.length
  }
}];

const text = $input.first().json.text || $input.first().json.html || '';
const subject = $input.first().json.subject || '';

// Immatriculation
const immatRegex = /\b([A-Z]{2}[-\s]?\d{3}[-\s]?[A-Z]{2})\b/gi;
const immat = (text.match(immatRegex) || [])[0] || 'Non detectee';

// Kilometrage
const kmMatch = text.match(/([\d\s.]+)\s*km/i);
const km = kmMatch ? kmMatch[1] : 'Non indique';

// Prestations
const prestas = ['vidange','révision','freins','courroie','batterie','climatisation'];
const found = prestas.filter(p => text.toLowerCase().includes(p));

return [{
  json: {
    type: 'ENTRETIEN',
    sujet: subject,
    immatriculation: immat,
    kilometrage: km,
    prestations: found
  }
}];

const d = $input.first().json;
let msg = '';

if (d.type === 'PNEUS') {
  msg = '🛞 **RDV PNEUS**\n';
  msg += `Immat: ${d.immatriculation}\n`;
  msg += `Client: ${d.client}\n`;
  msg += `Societe: ${d.societe}\n`;
  msg += `Loueur: ${d.loueur}\n`;
  if (d.dimensions.length > 0) {
    msg += `Pneus: ${d.dimensions.join(', ')}\n`;
  }
  if (d.codesSAP.length > 0) {
    msg += `SAP: ${d.codesSAP.join(', ')}\n`;
  }
} else {
  msg = '🔧 **RDV ENTRETIEN**\n';
  msg += `Immat: ${d.immatriculation}\n`;
  msg += `KM: ${d.kilometrage}\n`;
  if (d.prestations.length > 0) {
    msg += `Presta: ${d.prestations.join(', ')}\n`;
  }
}

return [{ json: { discordMessage: msg } }];
